insert into public.receitas (id, nome, emoji, minutos, porcoes, regiao, itens, extras, passos, status) values
('r1', 'Cuscuz nordestino com ovo', '🌽', 15, 1, 'Nordeste', '[{"id":"taco_533","g":150,"texto":"1 prato raso de cuscuz de milho"},{"id":"taco_488","g":50,"texto":"1 ovo cozido"},{"id":"taco_157","g":40,"texto":"½ tomate picado"},{"id":"taco_260","g":3,"texto":"1 fio de azeite"}]'::jsonb, '["sal a gosto","coentro"]'::jsonb, '["Hidrate a flocão com água e sal por 10 minutos.","Cozinhe no vapor (cuscuzeira) por 10 minutos.","Cozinhe o ovo por 10 minutos.","Sirva com tomate, coentro e um fio de azeite."]'::jsonb, 'publicado'),
('r2', 'Escondidinho de mandioca', '🥘', 45, 1, 'Nordeste', '[{"id":"taco_129","g":150,"texto":"1 xícara de mandioca cozida amassada"},{"id":"taco_326","g":100,"texto":"100 g de carne moída refogada"},{"id":"taco_463","g":15,"texto":"1 fatia de muçarela"}]'::jsonb, '["cebola, alho e cheiro-verde"]'::jsonb, '["Cozinhe a mandioca até ficar macia e amasse como purê.","Refogue a carne com cebola e alho.","Monte: carne no fundo, purê por cima e queijo.","Leve ao forno por 15 minutos para gratinar."]'::jsonb, 'publicado'),
('r3', 'Tilápia grelhada com abóbora', '🐟', 30, 1, 'Centro-Oeste', '[{"id":"tbca_brc0486e","g":120,"texto":"1 filé de tilápia"},{"id":"taco_64","g":150,"texto":"1 xícara de abóbora cabotiá"},{"id":"taco_100","g":80,"texto":"1 xícara de brócolis"},{"id":"taco_260","g":5,"texto":"1 colher de chá de azeite"}]'::jsonb, '["limão, sal e pimenta"]'::jsonb, '["Tempere o peixe com limão e sal.","Grelhe 4 minutos de cada lado.","Cozinhe a abóbora e o brócolis no vapor.","Finalize com azeite."]'::jsonb, 'publicado'),
('r4', 'Tofu acebolado com arroz integral', '🥢', 25, 1, 'Todas', '[{"id":"tbca_brc0056t","g":120,"texto":"120 g de tofu firme"},{"id":"taco_1","g":120,"texto":"4 colheres de sopa de arroz integral"},{"id":"taco_100","g":80,"texto":"1 xícara de brócolis"},{"id":"taco_260","g":5,"texto":"1 colher de chá de azeite"}]'::jsonb, '["1 cebola em tiras","shoyu (opcional — contém soja)"]'::jsonb, '["Seque o tofu e corte em cubos.","Doure no azeite com a cebola.","Cozinhe o brócolis no vapor.","Sirva com o arroz integral."]'::jsonb, 'publicado'),
('r5', 'Salada de grão-de-bico', '🥗', 10, 1, 'Todas', '[{"id":"tbca_brc0278t","g":150,"texto":"1 concha de grão-de-bico cozido"},{"id":"taco_157","g":60,"texto":"½ tomate"},{"id":"taco_142","g":50,"texto":"½ pepino"},{"id":"taco_78","g":30,"texto":"folhas de alface"},{"id":"taco_260","g":5,"texto":"1 colher de chá de azeite"}]'::jsonb, '["limão, sal e salsinha"]'::jsonb, '["Escorra o grão-de-bico.","Pique tomate e pepino.","Misture tudo e tempere com limão, azeite e sal."]'::jsonb, 'publicado'),
('r6', 'Vitamina de banana com aveia', '🍌', 5, 1, 'Todas', '[{"id":"taco_448","g":170,"texto":"1 pote de iogurte natural"},{"id":"taco_182","g":70,"texto":"1 banana prata"},{"id":"taco_7","g":15,"texto":"1 colher de sopa de aveia"},{"id":"taco_507","g":10,"texto":"1 colher de chá de mel"}]'::jsonb, '["canela (opcional)"]'::jsonb, '["Bata tudo no liquidificador.","Sirva gelado."]'::jsonb, 'publicado'),
('r7', 'Feijoada de domingo', '🍲', 120, 1, 'Sudeste', '[{"id":"taco_540","g":250,"texto":"1 concha grande de feijoada"},{"id":"taco_3","g":100,"texto":"4 colheres de sopa de arroz"},{"id":"taco_116","g":40,"texto":"couve refogada"},{"id":"taco_208","g":100,"texto":"1 laranja"}]'::jsonb, '["farofa (opcional)"]'::jsonb, '["Deixe o feijão e as carnes de molho na véspera.","Cozinhe na pressão por 40 minutos.","Refogue a couve com alho.","Sirva com arroz e laranja — a vitamina C ajuda a absorver o ferro do feijão."]'::jsonb, 'publicado')
